-- Create "contests" table
CREATE TABLE "contests" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "slug" character varying NOT NULL, "title" character varying NOT NULL, "description_md" text NOT NULL DEFAULT '', "starts_at" timestamptz NOT NULL, "freeze_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "status" character varying NOT NULL DEFAULT 'scheduled', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "contests_slug_key" to table: "contests"
CREATE UNIQUE INDEX "contests_slug_key" ON "contests" ("slug");
-- Create "contest_participants" table
CREATE TABLE "contest_participants" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "registered_at" timestamptz NOT NULL, "contest_id" bigint NOT NULL, "user_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "contest_participants_contests_participants" FOREIGN KEY ("contest_id") REFERENCES "contests" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "contest_participants_users_contests" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "contestparticipant_contest_id_user_id" to table: "contest_participants"
CREATE UNIQUE INDEX "contestparticipant_contest_id_user_id" ON "contest_participants" ("contest_id", "user_id");
-- Create "contest_problems" table
CREATE TABLE "contest_problems" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "label" character varying NOT NULL, "contest_id" bigint NOT NULL, "problem_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "contest_problems_contests_problems" FOREIGN KEY ("contest_id") REFERENCES "contests" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "contest_problems_problems_contest_entries" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "contestproblem_contest_id_label" to table: "contest_problems"
CREATE UNIQUE INDEX "contestproblem_contest_id_label" ON "contest_problems" ("contest_id", "label");
-- Create index "contestproblem_contest_id_problem_id" to table: "contest_problems"
CREATE UNIQUE INDEX "contestproblem_contest_id_problem_id" ON "contest_problems" ("contest_id", "problem_id");
-- Modify "submissions" table
ALTER TABLE "submissions" ADD COLUMN "contest_id" bigint NULL, ADD CONSTRAINT "submissions_contests_submissions" FOREIGN KEY ("contest_id") REFERENCES "contests" ("id") ON UPDATE NO ACTION ON DELETE SET NULL;
-- Create index "submission_contest_id_user_id_created_at" to table: "submissions"
CREATE INDEX "submission_contest_id_user_id_created_at" ON "submissions" ("contest_id", "user_id", "created_at");
